,3);assert.equal(orderBoxes(12,10,4),0)\n for(const v of [NaN,Infinity,-Infinity,'2',undefined,null,true,{},[]])for(let i=0;i<3;i++){const args=[1,3,1];args[i]=v;assert.throws(()=>orderBoxes(...args),RangeError)}\n assert.equal(orderBoxes(0,Number.MIN_VALUE,Number.MIN_VALUE),1);assert.equal(orderBoxes(0,Number.MAX_SAFE_INTEGER,1),Number.MAX_SAFE_INTEGER);assert.throws(()=>orderBoxes(0,Number.MAX_VALUE,Number.MIN_VALUE),RangeError)\n})\ntest('duration examples preserve safe-integer input validation and exact remainder values',()=>{\n for(const s of [0,59,60,119,120,3600,Number.MAX_SAFE_INTEGER]){const n=BigInt(s);assert.equal(formatDuration(s),(n/60n)+'m '+(n%60n)+'s')}\n for(const s of [Number.MAX_SAFE_INTEGER+1,-1,1.5,NaN,Infinity,'60',null,undefined,{},60n])assert.throws(()=>formatDuration(s),RangeError)\n})\n"},"draftContract":{"expectedTests":3,"criteria":[{"id":1,"text":"One top-level acceptance test preserves the existing exact-decimal orderBoxes examples and validation assertions from the read-only examples.test.js, including at least one executable assert comparison containing a direct selected-relative require('../src/localBrain/examples/stock.js').orderBoxes(...) call; stock.js remains byte-identical.","requiredSubjects":[{"file":"src/localBrain/examples/stock.js","symbol":"orderBoxes"}]},{"id":2,"text":"One top-level acceptance test preserves every existing formatDuration valid and invalid assertion from the read-only examples.test.js, including MAX_SAFE_INTEGER, and its export, with at least one executable assert comparison directly invoking require('../src/localBrain/examples/duration.js').formatDuration(...).","requiredSubjects":[{"file":"src/localBrain/examples/duration.js","symbol":"formatDuration"}]},{"id":3,"text":"One top-level acceptance test exercises the new exported formatClockDuration, including an executable assert comparison directly invoking require('../src/localBrain/examples/duration.js').formatClockDuration(...): 0=00:00:00; 9=00:00:09;